import { createSignal } from "solid-js";
import { AlertDialog } from "quoin-ui/alert-dialog";
const styles = {"Button":"Button","Backdrop":"Backdrop","Popup":"Popup","Title":"Title","Description":"Description","Actions":"Actions"};

// Same demo against our Solid v2 library. v2's AlertDialog.Root is
// controlled-only (no `defaultOpen`), so a signal mirrors React's
// closed-by-default behavior.
export default function ExampleAlertDialog() {
	const [open, setOpen] = createSignal(false);
	return (
		<AlertDialog.Root open={open()} onOpenChange={(next) => setOpen(next)}>
			<AlertDialog.Trigger data-color="red" class={styles.Button}>
				Discard draft
			</AlertDialog.Trigger>
			<AlertDialog.Portal>
				<AlertDialog.Backdrop class={styles.Backdrop} />
				<AlertDialog.Popup class={styles.Popup}>
					<AlertDialog.Title class={styles.Title}>
						Discard draft?
					</AlertDialog.Title>
					<AlertDialog.Description class={styles.Description}>
						You can't undo this action.
					</AlertDialog.Description>
					<div class={styles.Actions}>
						<AlertDialog.Close class={styles.Button}>Cancel</AlertDialog.Close>
						<AlertDialog.Close data-color="red" class={styles.Button}>
							Discard
						</AlertDialog.Close>
					</div>
				</AlertDialog.Popup>
			</AlertDialog.Portal>
		</AlertDialog.Root>
	);
}

