import type { ComponentProps } from "@solidjs/web";
import { createSignal } from "solid-js";
import { Checkbox } from "quoin-ui/checkbox";
import { CheckboxGroup } from "quoin-ui/checkbox-group";
const styles = {"CheckboxGroup":"CheckboxGroup","Caption":"Caption","Item":"Item","Checkbox":"Checkbox","Indicator":"Indicator","Icon":"Icon"};

// Same demo against our Solid v2 library. v2's CheckboxGroup is controlled-only
// (no `defaultValue`), so a signal mirrors React's uncontrolled default.
export default function ExampleCheckboxGroup() {
	const [value, setValue] = createSignal<string[]>(["fuji-apple"]);
	return (
		<CheckboxGroup
			aria-labelledby="apples-caption"
			value={value()}
			onValueChange={(next) => setValue(next as string[])}
			class={styles.CheckboxGroup}
		>
			<div class={styles.Caption} id="apples-caption">
				Apples
			</div>

			{/* biome-ignore lint/a11y/noLabelWithoutControl: Base UI Checkbox.Root renders the labelable control inside this label */}
			<label class={styles.Item}>
				<Checkbox.Root name="apple" value="fuji-apple" class={styles.Checkbox}>
					<Checkbox.Indicator class={styles.Indicator}>
						<CheckIcon class={styles.Icon} />
					</Checkbox.Indicator>
				</Checkbox.Root>
				Fuji
