import type { ComponentProps } from "@solidjs/web";
import { createSignal } from "solid-js";
import { Collapsible } from "quoin-ui/collapsible";
const styles = {"Collapsible":"Collapsible","Trigger":"Trigger","Icon":"Icon","Panel":"Panel","Content":"Content"};

// Same demo against our Solid v2 library. v2's Collapsible.Root is
// controlled-only (no `defaultOpen`), so a signal drives the open state.
export default function ExampleCollapsible() {
	const [open, setOpen] = createSignal(false);
	return (
		<Collapsible.Root
			class={styles.Collapsible}
			open={open()}
			onOpenChange={(next) => setOpen(next)}
		>
			<Collapsible.Trigger class={styles.Trigger}>
				<ChevronIcon class={styles.Icon} />
				Recovery keys
			</Collapsible.Trigger>
			<Collapsible.Panel class={styles.Panel}>
				<div class={styles.Content}>
					<div>alien-bean-pasta</div>
					<div>wild-irish-burrito</div>
					<div>horse-battery-staple</div>
				</div>
			</Collapsible.Panel>
		</Collapsible.Root>
	);
}

export function ChevronIcon(props: ComponentProps<"svg">) {
	return (
		<svg
			aria-hidden="true"
			width="10"
			height="10"
			viewBox="0 0 10 10"
			fill="none"
			{...props}
		>
			<path d="M3.5 9L7.5 5L3.5 1" stroke="currentcolor" />
		</svg>
	);
}

