import { createSignal } from "solid-js";
import { Field } from "quoin-ui/field";
import { Form, type FormErrors } from "quoin-ui/form";
const styles = {"Form":"Form","Field":"Field","Label":"Label","Input":"Input","Error":"Error","Button":"Button"};

export default function ExampleForm() {
	const [errors, setErrors] = createSignal<FormErrors>({});
	const [url, setUrl] = createSignal("https://example.com");
	const [loading, setLoading] = createSignal(false);

	return (
		<Form
			class={styles.Form}
			errors={errors()}
			onSubmit={async (event) => {
				event.preventDefault();
				const formData = new FormData(event.currentTarget);
				const value = formData.get("url") as string;

				setLoading(true);
				const response = await submitForm(value);
				const serverErrors: FormErrors = response.error
					? { url: response.error }
					: {};

				if (url() === value) setErrors(serverErrors);
				setLoading(false);
			}}
		>
			<Field.Root name="url" class={styles.Field}>
				<Field.Label class={styles.Label}>Homepage</Field.Label>
				<Field.Control
					type="url"
					required
					value={url()}
					onInput={(event) => { setUrl(event.currentTarget.value); setErrors({}); }}
					placeholder="https://example.com"
					pattern="https?://.*"
					class={styles.Input}
				/>
				<Field.Error class={styles.Error} />
			</Field.Root>
			<button disabled={loading()} type="submit" class={styles.Button}>
				Submit
			</button>
		</Form>
	);
}

async function submitForm(value: string) {
	// Mimic a server response
	await new Promise((resolve) => {
		setTimeout(resolve, 1000);
	});

	try {
		const url = new URL(value);

		if (url.hostname.endsWith("example.com")) {
			return { error: "The example domain is not allowed" };
		}
	} catch {
		return { error: "This is not a valid URL" };
	}

	return { success: true };
}

