import type { JSX } from "@solidjs/web";
import { createSignal } from "solid-js";
import { Menu } from "quoin-ui/menu";
const styles = {"Button":"Button","ButtonIcon":"ButtonIcon","Positioner":"Positioner","Popup":"Popup","Arrow":"Arrow","Item":"Item","Separator":"Separator","ArrowFill":"ArrowFill","ArrowOuterStroke":"ArrowOuterStroke","ArrowInnerStroke":"ArrowInnerStroke"};

// Same demo against our Solid v2 library. v2's Menu.Root is controlled-only
// (no internal open fallback), so a signal mirrors React's uncontrolled menu.
export default function ExampleMenu() {
	const [open, setOpen] = createSignal(false);
  const [submenuOpen, setSubmenuOpen] = createSignal(false);
  const [selected, setSelected] = createSignal("No action selected");
	return (
		<><Menu.Root open={open()} onOpenChange={(next) => { setOpen(next); if (!next) setSubmenuOpen(false); }}>
			<Menu.Trigger class={styles.Button}>
				Song <ChevronDownIcon class={styles.ButtonIcon} />
			</Menu.Trigger>
			<Menu.Portal>
				<Menu.Positioner class={styles.Positioner} sideOffset={8}>
					<Menu.Popup class={styles.Popup}>
						<Menu.Arrow class={styles.Arrow}>
							<ArrowSvg />
						</Menu.Arrow>
						<Menu.Item class={styles.Item} onClick={() => setSelected("Add to Library")}>Add to Library</Menu.Item>
						<Menu.Item class={styles.Item} onClick={() => setSelected("Add to Playlist")}>Add to Playlist</Menu.Item>
						<Menu.Separator class={styles.Separator} />
						<Menu.Item class={styles.Item} onClick={() => setSelected("Play Next")}>Play Next</Menu.Item>
						<Menu.Item class={styles.Item} onClick={() => setSelected("Play Last")}>Play Last</Menu.Item>
						<Menu.Separator class={styles.Separator} />
						<Menu.Item class={styles.Item} onClick={() => setSelected("Favorite")}>Favorite</Menu.Item>
						<Menu.SubmenuRoot open={submenuOpen()} onOpenChange={setSubmenuOpen}>
              <Menu.SubmenuTrigger class={styles.Item}>Share</Menu.SubmenuTrigger>
              <Menu.Portal><Menu.Positioner class={styles.Positioner} side="right" sideOffset={4}>
                <Menu.Popup class={styles.Popup}>
                  <Menu.Item class={styles.Item} onClick={() => { setSelected("Copy link selected"); setSubmenuOpen(false); setOpen(false); }}>Copy link</Menu.Item>
                  <Menu.Item class={styles.Item} onClick={() => { setSelected("Email selected"); setSubmenuOpen(false); setOpen(false); }}>Email</Menu.Item>
                </Menu.Popup>
              </Menu.Positioner></Menu.Portal>
            </Menu.SubmenuRoot>
					</Menu.Popup>
				</Menu.Positioner>
			</Menu.Portal>
		</Menu.Root><output aria-live="polite">{selected()}</output></>
	);
}

