import type { JSX } from "@solidjs/web";
import { createSignal } from "solid-js";
import { Menu } from "quoin-ui/menu";
import { Menubar } from "quoin-ui/menubar";
const styles = {"Menubar":"Menubar","MenuTrigger":"MenuTrigger","MenuPositioner":"MenuPositioner","MenuPopup":"MenuPopup","MenuItem":"MenuItem","MenuSeparator":"MenuSeparator"};

// Same demo against our Solid v2 library. v2's Menu.Root / Menu.SubmenuRoot are
// controlled-only (no internal open fallback), so each menu and submenu owns a
// local signal threaded through `open` + `onOpenChange` to mirror React's
// uncontrolled menubar.
export default function ExampleMenubar() {
	return (
		<Menubar class={styles.Menubar}>
			<FileMenu />
			<EditMenu />
			<ViewMenu />

			<DisabledMenu />
		</Menubar>
	);
}

function FileMenu() {
	const [open, setOpen] = createSignal(false);
	return (
		<Menu.Root open={open()} onOpenChange={(next) => setOpen(next)}>
			<Menu.Trigger class={styles.MenuTrigger}>File</Menu.Trigger>
			<Menu.Portal>
				<Menu.Positioner
					class={styles.MenuPositioner}
					sideOffset={6}
					alignOffset={-2}
				>
					<Menu.Popup class={styles.MenuPopup}>
						<Menu.Item class={styles.MenuItem} onClick={handleClick}>
							New
						</Menu.Item>
						<Menu.Item class={styles.MenuItem} onClick={handleClick}>
							Open
						</Menu.Item>
						<Menu.Item class={styles.MenuItem} onClick={handleClick}>
							Save
						</Menu.Item>

						<ExportSubmenu onSelect={() => setOpen(false)} />

						<Menu.Separator class={styles.MenuSeparator} />
						<Menu.Item class={styles.MenuItem} onClick={handleClick}>
							Print
						</Menu.Item>
					</Menu.Popup>
				</Menu.Positioner>
			</Menu.Portal>
		</Menu.Root>
	);
}

function ExportSubmenu(props: { onSelect: () => void }) {
	const [open, setOpen] = createSignal(false);
	return (
		<Menu.SubmenuRoot open={open()} onOpenChange={(next) => setOpen(next)}>
			<Menu.SubmenuTrigger class={styles.MenuItem}>
				Export
				<ChevronRightIcon />
			</Menu.SubmenuTrigger>
			<Menu.Portal>
				<Menu.Positioner alignOffset={-4}>
					<Menu.Popup class={styles.MenuPopup}>
						<Menu.Item class={styles.MenuItem} onClick={(event) => { handleClick(event); props.onSelect(); }}>
							PDF
						</Menu.Item>
						<Menu.Item class={styles.MenuItem} onClick={(event) => { handleClick(event); props.onSelect(); }}>
							PNG
						</Menu.Item>
						<Menu.Item class={styles.MenuItem} onClick={(event) => { handleClick(event); props.onSelect(); }}>
							SVG
						</Menu.Item>
					</Menu.Popup>
				</Menu.Positioner>
			</Menu.Portal>
		</Menu.SubmenuRoot>
	);
}

function EditMenu() {
	const [open, setOpen] = createSignal(false);
	return (
		<Menu.Root open={open()} onOpenChange={(next) => setOpen(next)}>
			<Menu.Trigger class={styles.MenuTrigger}>Edit</Menu.Trigger>
			<Menu.Portal>
				<Menu.Positioner class={styles.MenuPositioner} sideOffset={6}>
					<Menu.Popup class={styles.MenuPopup}>
						<Menu.Item class={styles.MenuItem} onClick={handleClick}>
							Cut
						</Menu.Item>
						<Menu.Item class={styles.MenuItem} onClick={handleClick}>
							Copy
						</Menu.Item>
						<Menu.Item class={styles.MenuItem} onClick={handleClick}>
							Paste
						</Menu.Item>
					</Menu.Popup>
				</Menu.Positioner>
			</Menu.Portal>
		</Menu.Root>
	);
