function ViewMenu() {
	const [open, setOpen] = createSignal(false);
	return (
		<Menu.Root open={open()} onOpenChange={(next) => setOpen(next)}>
			<Menu.Trigger class={styles.MenuTrigger}>View</Menu.Trigger>
