							Zoom In
						</Menu.Item>
						<Menu.Item class={styles.MenuItem} onClick={handleClick}>
							Zoom Out
						</Menu.Item>

						<LayoutSubmenu onSelect={() => setOpen(false)} />

						<Menu.Separator class={styles.MenuSeparator} />
						<Menu.Item class={styles.MenuItem} onClick={handleClick}>
							Full Screen
						</Menu.Item>
					</Menu.Popup>
				</Menu.Positioner>
			</Menu.Portal>
		</Menu.Root>
