  --color-popup-fg: var(--color-fg);
  --color-hover: transparent;
  --color-surface: var(--color-bg);
}
button, input { font: inherit; color: inherit; background: transparent; }
.Popup { padding: 0.75rem; background: var(--color-bg); color: var(--color-fg); border: 1px solid var(--color-border); }
[role=option] { padding: 0.25rem 0.5rem; }
.Root {
	background-color: var(--color-gray-50);
	border-radius: 0;
	padding: 0.25rem;
	color: var(--color-gray-900);
	min-width: max-content;
}

.List {
	display: flex;
	position: relative;
}

.Trigger {
	box-sizing: border-box;
	display: flex;
	align-items: center;
	justify-content: center;
	gap: 0.375rem;
	height: 2.5rem;
	padding: 0 0.875rem;
	margin: 0;
	outline: 0;
	border: none;
	border-radius: 0;
	background-color: var(--color-gray-50);
	font-family: inherit;
	font-size: 1rem;
	font-weight: 500;
	line-height: 1.5rem;
	color: var(--color-gray-900);
	user-select: none;
	text-decoration: none;

	@media (max-width: 500px) {
		font-size: 0.925rem;
		padding: 0 0.5rem;
	}

	@media (hover: hover) {
		&:hover {
		}
	}

	&[data-popup-open] {
		background-color: var(--color-gray-100);
	}

	&:focus-visible {
		position: relative;
		outline: 2px solid var(--color-blue);
		outline-offset: -1px;
	}
}

.Icon {
	transition: transform 0.2s ease;

	&[data-popup-open] {
		transform: rotate(180deg);
	}
}

.Positioner {
	--easing: cubic-bezier(0.22, 1, 0.36, 1);
	--duration: 0.35s;
	box-sizing: border-box;
	transition-property: top, left, right, bottom;
	transition-duration: var(--duration);
	transition-timing-function: var(--easing);
	width: var(--positioner-width);
	height: var(--positioner-height);
	max-width: var(--available-width);

	&::before {
		content: "";
		position: absolute;
	}

	&[data-side="top"]::before {
		left: 0;
		right: 0;
		bottom: -10px;
		height: 10px;
	}

	&[data-side="bottom"]::before {
		left: 0;
		right: 0;
		top: -10px;
		height: 10px;
	}

	&[data-side="left"]::before {
		top: 0;
		bottom: 0;
		right: -10px;
		width: 10px;
	}

	&[data-side="right"]::before {
		top: 0;
		bottom: 0;
		left: -10px;
		width: 10px;
	}

	&[data-instant] {
		transition: none;
	}
}

.Popup {
	position: relative;
	box-sizing: border-box;
	border-radius: 0;
	background-color: canvas;
	color: var(--color-gray-900);
	transform-origin: var(--transform-origin);
	transition-property: opacity, transform, width, height;
	transition-duration: var(--duration);
	transition-timing-function: var(--easing);
	width: max-content;
	height: var(--popup-height);

	@media (min-width: 500px) {
		width: var(--popup-width);
	}

	&[data-starting-style],
	&[data-ending-style] {
		opacity: 0;
		transform: scale(0.9);
	}

	&[data-ending-style] {
		transition-timing-function: ease;
		transition-duration: 0.15s;
	}
}

@media (prefers-color-scheme: light) {
	.Popup {
		outline: 1px solid var(--color-gray-200);
		box-shadow:
			0 10px 15px -3px var(--color-gray-200),
			0 4px 6px -4px var(--color-gray-200);
	}
}

:root.dark {
	.Popup {
		outline: 1px solid var(--color-gray-300);
		outline-offset: -1px;
	}
}

.Content {
	transition:
		opacity calc(var(--duration) * 0.5) ease,
		transform var(--duration) var(--easing);
	padding: 1.5rem;
	width: calc(100vw - 40px);
	height: 100%;

	@media (min-width: 500px) {
		width: max-content;
		min-width: 400px;
	}

	&[data-starting-style],
	&[data-ending-style] {
		opacity: 0;
	}

	&[data-starting-style] {
		&[data-activation-direction="left"] {
			transform: translateX(-50%);
		}
		&[data-activation-direction="right"] {
			transform: translateX(50%);
		}
	}

	&[data-ending-style] {
		&[data-activation-direction="left"] {
			transform: translateX(50%);
		}
		&[data-activation-direction="right"] {
			transform: translateX(-50%);
		}
	}
}

.Viewport {
	position: relative;
	overflow: hidden;
	width: 100%;
	height: 100%;
}

.GridLinkList {
	display: grid;
	grid-template-columns: 12rem 12rem;
	list-style: none;

	@media (max-width: 500px) {
		grid-template-columns: 1fr;
	}
}

.FlexLinkList {
	display: flex;
	flex-direction: column;
	justify-content: center;
	max-width: 400px;
}

.LinkCard {
	display: block;
	padding: 0.5rem;
	border-radius: 0;
	text-decoration: none;
	color: inherit;

	@media (hover: hover) {
		&:hover {
		}
	}

	&:focus-visible {
		position: relative;
		outline: 2px solid var(--color-blue);
		outline-offset: -1px;
	}

	@media (min-width: 425px) {
		& {
			padding: 0.75rem;
		}
	}
}

.LinkTitle {
	margin: 0 0 4px;
	font-size: 1rem;
	font-weight: 500;
	line-height: 1.25rem;
}

.LinkDescription {
	margin: 0;
	font-size: 0.875rem;
	line-height: 1.25rem;
	color: var(--color-gray-500);
}

.Arrow {
	display: flex;
	transition: left calc(var(--duration)) var(--easing);

	&[data-side="top"] {
		bottom: -8px;
		rotate: 180deg;
	}

	&[data-side="bottom"] {
		top: -8px;
		rotate: 0deg;
	}

	&[data-side="left"] {
		right: -13px;
		rotate: 90deg;
	}

	&[data-side="right"] {
		left: -13px;
		rotate: -90deg;
	}
}

.ArrowFill {
	fill: canvas;
}

.ArrowOuterStroke {
	@media (prefers-color-scheme: light) {
		fill: var(--color-gray-200);
	}
}

.ArrowInnerStroke {
	:root.dark & {
		fill: var(--color-gray-300);
	}
}

.List, .GridLinkList, .FlexLinkList { list-style: none; margin: 0; padding: 0; }
.Popup { padding: 0; max-width: calc(100vw - 16px); }
.Content { box-sizing: border-box; max-width: calc(100vw - 16px); max-height: calc(100vh - 96px); overflow-y: auto; padding: 1rem; }

