import type { JSX } from "@solidjs/web";
import { createSignal, createUniqueId } from "solid-js";
import { NumberField } from "quoin-ui/number-field";
const styles = {"Field":"Field","ScrubArea":"ScrubArea","Label":"Label","ScrubAreaCursor":"ScrubAreaCursor","Group":"Group","Decrement":"Decrement","Input":"Input","Increment":"Increment"};

// Same demo against our Solid v2 library. v2's NumberField.Root is
// controlled-only (no `defaultValue`), so a signal seeds the initial 100 and
// mirrors React's uncontrolled value. `createUniqueId` replaces React.useId
// for the label/input association.
export default function ExampleNumberField() {
	const id = createUniqueId();
	const [value, setValue] = createSignal<number | null>(100);
	return (
		<NumberField.Root
			id={id}
			value={value()}
			onValueChange={(next) => setValue(next)}
			class={styles.Field}
		>
			<NumberField.ScrubArea class={styles.ScrubArea}>
				<label for={id} class={styles.Label}>
					Amount
				</label>
				<NumberField.ScrubAreaCursor class={styles.ScrubAreaCursor}>
					<CursorGrowIcon />
				</NumberField.ScrubAreaCursor>
			</NumberField.ScrubArea>

			<NumberField.Group class={styles.Group}>
				<NumberField.Decrement class={styles.Decrement}>
					<MinusIcon />
				</NumberField.Decrement>
				<NumberField.Input class={styles.Input} />
				<NumberField.Increment class={styles.Increment}>
					<PlusIcon />
				</NumberField.Increment>
			</NumberField.Group>
		</NumberField.Root>
	);
}

function CursorGrowIcon(props: JSX.SvgSVGAttributes<SVGSVGElement>) {
