import { createSignal, onCleanup } from "solid-js";
import { Progress } from "quoin-ui/progress";
const styles = {"Progress":"Progress","Label":"Label","Value":"Value","Track":"Track","Indicator":"Indicator"};

// Same demo against our Solid v2 library. Mirrors React's setInterval simulation
// with a signal; no onMount/createEffect needed since the timer is set up at
// module-eval time during component setup.
export default function ExampleProgress() {
	const [value, setValue] = createSignal(20);

	const interval = setInterval(() => {
		setValue((current) =>
			Math.min(100, Math.round(current + Math.random() * 25)),
		);
	}, 1000);
	onCleanup(() => clearInterval(interval));

	return (
		<Progress.Root class={styles.Progress} value={value()}>
			<Progress.Label class={styles.Label}>Export data</Progress.Label>
			<Progress.Value class={styles.Value} />
			<Progress.Track class={styles.Track}>
				<Progress.Indicator class={styles.Indicator} />
			</Progress.Track>
		</Progress.Root>
	);
}

