import { createSignal } from "solid-js";
import { Radio } from "quoin-ui/radio";
import { RadioGroup } from "quoin-ui/radio-group";
const styles = {"RadioGroup":"RadioGroup","Caption":"Caption","Item":"Item","Radio":"Radio","Indicator":"Indicator"};

// v2 RadioGroup is controlled-only (no `defaultValue`), so a signal mirrors
// React's uncontrolled default.
export default function ExampleRadioGroup() {
	const [value, setValue] = createSignal<string>("fuji-apple");
	return (
		<RadioGroup
			aria-labelledby="apples-caption"
			value={value()}
			onValueChange={(next) => setValue(next as string)}
			class={styles.RadioGroup}
		>
			<div class={styles.Caption} id="apples-caption">
				Best apple
			</div>

			{/* biome-ignore lint/a11y/noLabelWithoutControl: Base UI Radio.Root renders the labelable control inside this label */}
			<label class={styles.Item}>
				<Radio.Root value="fuji-apple" class={styles.Radio}>
					<Radio.Indicator class={styles.Indicator} />
				</Radio.Root>
				Fuji
			</label>

			{/* biome-ignore lint/a11y/noLabelWithoutControl: Base UI Radio.Root renders the labelable control inside this label */}
			<label class={styles.Item}>
				<Radio.Root value="gala-apple" class={styles.Radio}>
					<Radio.Indicator class={styles.Indicator} />
				</Radio.Root>
				Gala
			</label>

			{/* biome-ignore lint/a11y/noLabelWithoutControl: Base UI Radio.Root renders the labelable control inside this label */}
			<label class={styles.Item}>
				<Radio.Root value="granny-smith-apple" class={styles.Radio}>
					<Radio.Indicator class={styles.Indicator} />
				</Radio.Root>
				Granny Smith
			</label>
		</RadioGroup>
	);
}

