import type { JSX } from "@solidjs/web";
import { createSignal, For } from "solid-js";
import { Select } from "quoin-ui/select";
const styles = {"Select":"Select","SelectIcon":"SelectIcon","Positioner":"Positioner","ScrollArrow":"ScrollArrow","Popup":"Popup","Item":"Item","ItemIndicator":"ItemIndicator","ItemIndicatorIcon":"ItemIndicatorIcon","ItemText":"ItemText"};

const fonts = [
	{ label: "Select font", value: null },
	{ label: "Sans-serif", value: "sans" },
	{ label: "Serif", value: "serif" },
	{ label: "Monospace", value: "mono" },
	{ label: "Cursive", value: "cursive" },
];

// v2's Select.Root is controlled-only (no `defaultValue`), so a signal mirrors
// React's uncontrolled default of `null` (the first item, "Select font").
export default function ExampleSelect() {
	const [open, setOpen] = createSignal(false);
	const [value, setValue] = createSignal<string | null>(null);
	return (
		<Select.Root
			items={fonts}
			open={open()}
			onOpenChange={setOpen}
			value={value()}
			onValueChange={(next) => setValue(next as string | null)}
		>
			<Select.Trigger class={styles.Select}>
				<Select.Value />
				<Select.Icon class={styles.SelectIcon}>
					<ChevronUpDownIcon />
				</Select.Icon>
			</Select.Trigger>
			<Select.Portal>
				<Select.Positioner class={styles.Positioner} sideOffset={8}>
					<Select.ScrollUpArrow class={styles.ScrollArrow} />
					<Select.Popup class={styles.Popup}>
						<For each={fonts}>
							{(font) => (
								<Select.Item value={font.value} class={styles.Item}>
									<Select.ItemIndicator class={styles.ItemIndicator}>
										<CheckIcon class={styles.ItemIndicatorIcon} />
									</Select.ItemIndicator>
									<Select.ItemText class={styles.ItemText}>
										{font.label}
									</Select.ItemText>
								</Select.Item>
							)}
						</For>
					</Select.Popup>
					<Select.ScrollDownArrow class={styles.ScrollArrow} />
				</Select.Positioner>
			</Select.Portal>
		</Select.Root>
	);
}

function ChevronUpDownIcon(props: JSX.IntrinsicElements["svg"]) {
	return (
		<svg
			aria-hidden="true"
			width="8"
			height="12"
			viewBox="0 0 8 12"
			fill="none"
			stroke="currentcolor"
			stroke-width="1.5"
			{...props}
		>
			<path d="M0.5 4.5L4 1.5L7.5 4.5" />
			<path d="M0.5 7.5L4 10.5L7.5 7.5" />
		</svg>
	);
}

function CheckIcon(props: JSX.IntrinsicElements["svg"]) {
	return (
		<svg
			aria-hidden="true"
			fill="currentcolor"
			width="10"
			height="10"
			viewBox="0 0 10 10"
			{...props}
		>
			<path d="M9.1603 1.12218C9.50684 1.34873 9.60427 1.81354 9.37792 2.16038L5.13603 8.66012C5.01614 8.8438 4.82192 8.96576 4.60451 8.99384C4.3871 9.02194 4.1683 8.95335 4.00574 8.80615L1.24664 6.30769C0.939709 6.02975 0.916013 5.55541 1.19372 5.24822C1.47142 4.94102 1.94536 4.91731 2.2523 5.19524L4.36085 7.10461L8.12299 1.33999C8.34934 0.993152 8.81376 0.895638 9.1603 1.12218Z" />
		</svg>
	);
}

