		inset-inline: 0.25rem;
		border-radius: 0;
	}
}

.ItemIndicator {
	grid-column-start: 1;
}

.ItemIndicatorIcon {
	display: block;
	width: 0.75rem;
	height: 0.75rem;
}

.ItemText {
	grid-column-start: 2;
}

.ScrollArrow {
	width: 100%;
	background: canvas;
	z-index: 1;
	text-align: center;
	cursor: default;
	border-radius: 0;
	height: 1rem;
	font-size: 0.75rem;
	display: flex;
	align-items: center;
	justify-content: center;

	&::before {
		content: "";
		position: absolute;
		width: 100%;
		height: 100%;
		left: 0;
	}

	&[data-direction="up"] {
		&::before {
			top: -100%;
		}
	}

	&[data-direction="down"] {
		bottom: 0;

		&::before {
			bottom: -100%;
		}
	}
}

