import { createSignal } from "solid-js";
import { Switch } from "quoin-ui/switch";
const styles = {"Switch":"Switch","Thumb":"Thumb"};

// Same demo against our Solid v2 library. v2's Switch.Root is controlled-only
// (no `defaultChecked`), so a signal mirrors React's uncontrolled default.
export default function ExampleSwitch() {
	const [checked, setChecked] = createSignal(true);
