import type { JSX } from "@solidjs/web";
import { createSignal, For } from "solid-js";
import { Toast, useToastManager } from "quoin-ui/toast";
const styles = {"Viewport":"Viewport","Button":"Button","Toast":"Toast","Content":"Content","Title":"Title","Description":"Description","Close":"Close","Icon":"Icon"};

export default function ExampleToast() {
	return (
		<Toast.Provider>
			<ToastButton />
			<Toast.Portal>
				<Toast.Viewport class={styles.Viewport}>
					<ToastList />
				</Toast.Viewport>
			</Toast.Portal>
		</Toast.Provider>
	);
}

function ToastButton() {
	const toastManager = useToastManager();
	const [count, setCount] = createSignal(0);

	function createToast() {
		setCount((prev) => prev + 1);
		toastManager.add({
			title: `Toast ${count() + 1} created`,
			description: "This is a toast notification.",
		});
	}

	return (
		<button type="button" class={styles.Button} onClick={createToast}>
			Create toast
		</button>
	);
}

function ToastList() {
	// `toasts` is a reactive accessor in v2 (not a plain array snapshot).
	const { toasts } = useToastManager();
	return (
		<For each={toasts()} keyed={(t) => t.id}>
			{(toast) => (
				<Toast.Root toast={toast()} class={styles.Toast}>
					<Toast.Content class={styles.Content}>
						<Toast.Title class={styles.Title} />
						<Toast.Description class={styles.Description} />
						<Toast.Close class={styles.Close} aria-label="Close">
							<XIcon class={styles.Icon} />
						</Toast.Close>
					</Toast.Content>
				</Toast.Root>
			)}
		</For>
	);
}

function XIcon(props: JSX.IntrinsicElements["svg"]) {
	return (
		<svg
			aria-hidden="true"
			xmlns="http://www.w3.org/2000/svg"
			width="24"
			height="24"
			viewBox="0 0 24 24"
			fill="none"
			stroke="currentColor"
			stroke-width="2"
			stroke-linecap="round"
			stroke-linejoin="round"
			{...props}
		>
			<path d="M18 6 6 18" />
			<path d="m6 6 12 12" />
		</svg>
	);
}

