import type { JSX } from "@solidjs/web";
import { createSignal } from "solid-js";
import { Select } from "quoin-ui/select";
import { Toggle } from "quoin-ui/toggle";
import { ToggleGroup } from "quoin-ui/toggle-group";
import { Toolbar } from "quoin-ui/toolbar";
const styles = {"Toolbar":"Toolbar","Group":"Group","Button":"Button","Separator":"Separator","Positioner":"Positioner","Popup":"Popup","Arrow":"Arrow","Item":"Item","ItemIndicator":"ItemIndicator","ItemIndicatorIcon":"ItemIndicatorIcon","ItemText":"ItemText","Link":"Link","ArrowFill":"ArrowFill","ArrowOuterStroke":"ArrowOuterStroke","ArrowInnerStroke":"ArrowInnerStroke"};

// v2 removed the `render={<Component />}` prop (§1 wave 4). Composition is now
// expressed with `as={Component}`: ToolbarButton renders the supplied component
// (Toggle / Select.Trigger) and forwards merged props/refs to it.
//
// v2 ToggleGroup and Select.Root are controlled-only (no `defaultValue`), so
// signals mirror React's uncontrolled defaults.
export default function ExampleToolbar() {
	const [alignment, setAlignment] = createSignal<readonly string[]>([]);
	const [font, setFont] = createSignal<string>("Helvetica");
	const [fontSelectOpen, setFontSelectOpen] = createSignal(false);

	return (
		<Toolbar.Root class={styles.Toolbar}>
			<ToggleGroup
				class={styles.Group}
				aria-label="Alignment"
				value={alignment()}
				onValueChange={(next) => setAlignment(next)}
			>
				<Toolbar.Button
					as={Toggle}
					aria-label="Align left"
					value="align-left"
					class={styles.Button}
				>
					Align Left
				</Toolbar.Button>
				<Toolbar.Button
					as={Toggle}
					aria-label="Align right"
					value="align-right"
					class={styles.Button}
				>
					Align Right
				</Toolbar.Button>
			</ToggleGroup>
			<Toolbar.Separator class={styles.Separator} />
			<Toolbar.Group class={styles.Group} aria-label="Numerical format">
				<Toolbar.Button class={styles.Button} aria-label="Format as currency">
					$
				</Toolbar.Button>
				<Toolbar.Button class={styles.Button} aria-label="Format as percent">
					%
				</Toolbar.Button>
			</Toolbar.Group>
			<Toolbar.Separator class={styles.Separator} />
			<Select.Root
				open={fontSelectOpen()}
				onOpenChange={setFontSelectOpen}
				value={font()}
				onValueChange={(next) => setFont(next as string)}
			>
				<Toolbar.Button as={Select.Trigger} class={styles.Button}>
					<Select.Value />
					<Select.Icon>
						<ChevronUpDownIcon />
					</Select.Icon>
				</Toolbar.Button>
				<Select.Portal>
					<Select.Positioner class={styles.Positioner} sideOffset={8}>
						<Select.Popup class={styles.Popup}>
							<Select.Arrow class={styles.Arrow}>
								<ArrowSvg />
							</Select.Arrow>
							<Select.Item class={styles.Item} value="Helvetica">
								<Select.ItemIndicator class={styles.ItemIndicator}>
									<CheckIcon class={styles.ItemIndicatorIcon} />
								</Select.ItemIndicator>
								<Select.ItemText class={styles.ItemText}>
									Helvetica
								</Select.ItemText>
							</Select.Item>
							<Select.Item class={styles.Item} value="Arial">
								<Select.ItemIndicator class={styles.ItemIndicator}>
									<CheckIcon class={styles.ItemIndicatorIcon} />
								</Select.ItemIndicator>
								<Select.ItemText class={styles.ItemText}>Arial</Select.ItemText>
							</Select.Item>
						</Select.Popup>
					</Select.Positioner>
				</Select.Portal>
			</Select.Root>
			<Toolbar.Separator class={styles.Separator} />
			<Toolbar.Link class={styles.Link} href="#">
				Edited 51m ago
			</Toolbar.Link>
		</Toolbar.Root>
	);
}

function ArrowSvg(props: JSX.SvgSVGAttributes<SVGSVGElement>) {
	return (
		<svg
			aria-hidden="true"
			width="20"
			height="10"
			viewBox="0 0 20 10"
			fill="none"
			{...props}
		>
			<path
				d="M9.66437 2.60207L4.80758 6.97318C4.07308 7.63423 3.11989 8 2.13172 8H0V10H20V8H18.5349C17.5468 8 16.5936 7.63423 15.8591 6.97318L11.0023 2.60207C10.622 2.2598 10.0447 2.25979 9.66437 2.60207Z"
				class={styles.ArrowFill}
