Toolbar.css:
:root {
  --color-gray-50: light-dark(#fafafa, #000);
  --color-gray-100: light-dark(#f2f2f2, #181818);
  --color-gray-200: light-dark(#e5e5e5, #333);
  --color-gray-300: light-dark(#ccc, #555);
  --color-gray-400: light-dark(#999, #aaa);
  --color-gray-500: light-dark(#666, #bbb);
  --color-gray-600: light-dark(#555, #ccc);
  --color-gray-700: light-dark(#333, #ddd);
  --color-gray-800: light-dark(#222, #eee);
  --color-gray-900: light-dark(#111, #fff);
  --color-gray-950: light-dark(#000, #fff);
  --color-blue: light-dark(#174ea6, #b4ceff);
  --color-red: light-dark(#b00020, #ffb4b4);
  --color-bg: light-dark(#fff, #000);
  --color-fg: light-dark(#111, #fff);
  --color-muted: light-dark(#555, #ccc);
  --color-border: light-dark(#ccc, #555);
  --color-popup: var(--color-bg);
  --color-popup-fg: var(--color-fg);
  --color-hover: transparent;
  --color-surface: var(--color-bg);
}
button, input { font: inherit; color: inherit; background: transparent; }
.Popup { padding: 0.75rem; background: var(--color-bg); color: var(--color-fg); border: 1px solid var(--color-border); }
[role=option] { padding: 0.25rem 0.5rem; }
.Toolbar {
	display: flex;
	align-items: center;
	gap: 1px;
	border: 1px solid var(--color-gray-200);
	background-color: var(--color-gray-50);
	border-radius: 0;
	padding: 0.125rem;
	width: 37.5rem;
}

.Group {
	display: flex;
	gap: 0.25rem;
}

.Button {
	box-sizing: border-box;
	display: flex;
	align-items: center;
	justify-content: center;
	min-width: 2rem;
	height: 2rem;
	padding: 0;
	margin: 0;
	outline: 0;
	border: 0;
	border-radius: 0;
	background-color: transparent;
	color: var(--color-gray-600);
	user-select: none;
	font-family: inherit;
	font-size: 0.875rem;
	font-weight: 500;

	&:focus-visible {
		background-color: transparent;
		outline: 2px solid var(--color-blue);
		outline-offset: -1px;
	}

	@media (hover: hover) {
		&:hover {
		}
	}

	&:active {
	}

	&[data-pressed] {
		background-color: var(--color-gray-100);
		color: var(--color-gray-900);
	}

	&[aria-pressed] {
		padding: 0 0.75rem;
	}

	&[role="combobox"] {
		min-width: 8rem;
		justify-content: space-between;
		padding: 0 0.75rem;
	}
}

.Separator {
	width: 1px;
	height: 16px;
	margin: 0.25rem;
	background-color: var(--color-gray-300);
}

.Link {
	color: var(--color-gray-500);
	font-family: inherit;
	font-size: 0.875rem;
	text-decoration: none;
	align-self: center;
	flex: 0 0 auto;
	margin-inline: auto 0.875rem;

	&:focus-visible {
		outline: 2px solid var(--color-blue);
		outline-offset: -2px;
		border-radius: 0;
	}

	@media (hover: hover) {
		&:hover {
			color: inherit;
		}
	}
}

.Select {
	box-sizing: border-box;
	display: flex;
	align-items: center;
	justify-content: space-between;
	gap: 0.75rem;
	height: 2.5rem;
	padding-left: 0.875rem;
	padding-right: 0.75rem;
	margin: 0;
	outline: 0;
	border: 1px solid var(--color-gray-200);
	border-radius: 0;
	font-family: inherit;
	font-size: 1rem;
	line-height: 1.5rem;
	color: var(--color-gray-900);
	cursor: default;
	user-select: none;
	min-width: 9rem;

	@media (hover: hover) {
		&:hover {
		}
	}

	&:active {
	}

	&[data-popup-open] {
		background-color: var(--color-gray-100);
	}

	&:focus-visible {
		outline: 2px solid var(--color-blue);
		outline-offset: -1px;
	}
}

.SelectIcon {
	display: flex;
}

.Popup {
	box-sizing: border-box;
	padding-block: 0.25rem;
	border-radius: 0;
	background-color: canvas;
	color: var(--color-gray-900);
	transform-origin: var(--transform-origin);
	transition:
		transform 150ms,
		opacity 150ms;

	&[data-starting-style],
	&[data-ending-style] {
		opacity: 0;
		transform: scale(0.9);
	}

	&[data-side="none"] {
		transition: none;
		transform: none;
		opacity: 1;
	}

	@media (prefers-color-scheme: light) {
		outline: 1px solid var(--color-gray-200);
		box-shadow:
			0 10px 15px -3px var(--color-gray-200),
			0 4px 6px -4px var(--color-gray-200);
	}

	:root.dark & {
		outline: 1px solid var(--color-gray-300);
		outline-offset: -1px;
	}
}

.Arrow {
	display: flex;

	&[data-side="top"] {
		bottom: -8px;
		rotate: 180deg;
	}

	&[data-side="bottom"] {
		top: -8px;
		rotate: 0deg;
	}

	&[data-side="left"] {
		right: -13px;
		rotate: 90deg;
	}

	&[data-side="right"] {
		left: -13px;
		rotate: -90deg;
	}
}

.ArrowFill {
	fill: canvas;
}

.ArrowOuterStroke {
	@media (prefers-color-scheme: light) {
		fill: var(--color-gray-200);
	}
}

.ArrowInnerStroke {
	:root.dark & {
		fill: var(--color-gray-300);
	}
}

.Item {
	box-sizing: border-box;
	outline: 0;
	font-size: 0.875rem;
	line-height: 1rem;
	padding-block: 0.5rem;
	padding-left: 0.625rem;
	padding-right: 1rem;
	min-width: var(--anchor-width);
	display: grid;
	gap: 0.5rem;
	align-items: center;
	grid-template-columns: 0.75rem 1fr;
	cursor: default;
	user-select: none;

	[data-side="none"] & {
		font-size: 1rem;
		padding-right: 3rem;
		min-width: calc(var(--anchor-width) + 1rem);
	}

	&[data-highlighted] {
		z-index: 0;
		position: relative;
		color: inherit;
		text-decoration: underline;
	}

	&[data-highlighted]::before {
		content: "";
		z-index: -1;
		position: absolute;
		inset-block: 0;
		inset-inline: 0.25rem;
		border-radius: 0;
	}
}

.ItemIndicator {
	grid-column-start: 1;
}

.ItemIndicatorIcon {
	display: block;
	width: 0.75rem;
	height: 0.75rem;
}

.ItemText {
	grid-column-start: 2;
}

.Toolbar { box-sizing: border-box; max-width: 100%; flex-wrap: wrap; }

